-- Voyalo - MySQL 8+ (prix en FCFA)
CREATE DATABASE IF NOT EXISTS voyalo CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE voyalo;

CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, nom VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password VARCHAR(255) NOT NULL, telephone VARCHAR(30), role ENUM('client','agent','admin') NOT NULL DEFAULT 'client', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE hotels (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, nom VARCHAR(180) NOT NULL, ville VARCHAR(120) NOT NULL, adresse VARCHAR(255) NOT NULL, description TEXT, etoiles TINYINT UNSIGNED NOT NULL DEFAULT 3, image_principale VARCHAR(255), equipements JSON NULL, actif BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(ville)) ENGINE=InnoDB;
CREATE TABLE rooms (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, hotel_id BIGINT UNSIGNED NOT NULL, type VARCHAR(100) NOT NULL, capacite SMALLINT UNSIGNED NOT NULL, prix_nuit DECIMAL(12,0) NOT NULL, disponible BOOLEAN NOT NULL DEFAULT TRUE, image VARCHAR(255), FOREIGN KEY(hotel_id) REFERENCES hotels(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE room_bookings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, room_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, date_arrivee DATE NOT NULL, date_depart DATE NOT NULL, nb_personnes SMALLINT UNSIGNED NOT NULL, prix_total DECIMAL(12,0) NOT NULL, statut ENUM('en_attente','confirmee','payee','annulee','terminee') NOT NULL DEFAULT 'en_attente', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(room_id) REFERENCES rooms(id), FOREIGN KEY(user_id) REFERENCES users(id), INDEX(date_arrivee,date_depart,statut)) ENGINE=InnoDB;
CREATE TABLE routes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, origine VARCHAR(120) NOT NULL, destination VARCHAR(120) NOT NULL, type_transport ENUM('avion','bus') NOT NULL, compagnie VARCHAR(160) NOT NULL, prix DECIMAL(12,0) NOT NULL, places_totales SMALLINT UNSIGNED NOT NULL, actif BOOLEAN NOT NULL DEFAULT TRUE, INDEX(origine,destination)) ENGINE=InnoDB;
CREATE TABLE trips_schedule (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, route_id BIGINT UNSIGNED NOT NULL, date_depart DATE NOT NULL, heure_depart TIME NOT NULL, places_restantes SMALLINT UNSIGNED NOT NULL, FOREIGN KEY(route_id) REFERENCES routes(id) ON DELETE CASCADE, INDEX(date_depart,route_id)) ENGINE=InnoDB;
CREATE TABLE ticket_bookings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, schedule_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, nb_billets SMALLINT UNSIGNED NOT NULL, prix_total DECIMAL(12,0) NOT NULL, statut ENUM('en_attente','confirmee','payee','annulee','terminee') NOT NULL DEFAULT 'en_attente', code_billet VARCHAR(40) UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(schedule_id) REFERENCES trips_schedule(id), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE packages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, titre VARCHAR(180) NOT NULL, description TEXT, duree_jours SMALLINT UNSIGNED NOT NULL, prix DECIMAL(12,0) NOT NULL, itineraire TEXT, image_principale VARCHAR(255), actif BOOLEAN NOT NULL DEFAULT TRUE) ENGINE=InnoDB;
CREATE TABLE package_departures (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, package_id BIGINT UNSIGNED NOT NULL, date_depart DATE NOT NULL, places SMALLINT UNSIGNED NOT NULL DEFAULT 20, FOREIGN KEY(package_id) REFERENCES packages(id) ON DELETE CASCADE, INDEX(date_depart)) ENGINE=InnoDB;
CREATE TABLE package_bookings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, package_id BIGINT UNSIGNED NOT NULL, departure_id BIGINT UNSIGNED, user_id BIGINT UNSIGNED NOT NULL, nb_participants SMALLINT UNSIGNED NOT NULL, date_depart_choisie DATE NOT NULL, prix_total DECIMAL(12,0) NOT NULL, statut ENUM('en_attente','confirmee','payee','annulee','terminee') NOT NULL DEFAULT 'en_attente', created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(package_id) REFERENCES packages(id), FOREIGN KEY(departure_id) REFERENCES package_departures(id), FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB;
CREATE TABLE payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, booking_type ENUM('hotel','billet','forfait') NOT NULL, booking_id BIGINT UNSIGNED NOT NULL, montant DECIMAL(12,0) NOT NULL, methode ENUM('orange_money','mtn_momo','carte','cash') NOT NULL, statut ENUM('en_attente','reussi','echec','rembourse') NOT NULL DEFAULT 'en_attente', reference_transaction VARCHAR(100) UNIQUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX(booking_type,booking_id)) ENGINE=InnoDB;
CREATE TABLE reviews (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, hotel_id BIGINT UNSIGNED NOT NULL, user_id BIGINT UNSIGNED NOT NULL, note TINYINT UNSIGNED NOT NULL, commentaire TEXT, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, UNIQUE(hotel_id,user_id), FOREIGN KEY(hotel_id) REFERENCES hotels(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id), CHECK(note BETWEEN 1 AND 5)) ENGINE=InnoDB;
CREATE TABLE password_resets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expires_at DATETIME NOT NULL, used_at DATETIME NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE promotions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, code VARCHAR(40) NOT NULL UNIQUE, reduction_pct DECIMAL(5,2) NOT NULL, actif BOOLEAN NOT NULL DEFAULT TRUE, date_debut DATE, date_fin DATE) ENGINE=InnoDB;
